//! Track 6 sub-task 3b — server-side spell table.
//!
//! Mirror of the subset of `SpellDefinitions.ALL` the server needs to
//! process damage and heal spells. Generated by
//! `Project_Dawn/tools/export_spells.gd`; the file is embedded at
//! compile time and parsed once on first lookup.
//!
//! Out of scope (still client-side until sub-task 4 ports buff state):
//! HoT / DoT / CC / port / song / stat-buff / damage-shield / dispel /
//! pet / charm. Spells with those mechanics have only their damage /
//! heal component applied server-side; the rest fires client-local.

use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const SPELLS_TOML: &str = include_str!("../../data/spells.toml");

#[derive(Debug, Deserialize)]
struct SpellsFile {
    #[serde(rename = "spell")]
    spells: Vec<Spell>,
}

#[derive(Debug, Clone, Deserialize)]
#[allow(dead_code)] // cast_time + cooldown + classes consumed in later sub-tasks
pub struct Spell {
    pub name: String,
    pub target_type: String,
    pub damage_type: String,
    pub base_damage: f32,
    pub heal_amount: f32,
    pub mana_cost: f32,
    #[serde(default)]
    pub hp_cost: f32,
    pub cast_time: f32,
    pub cooldown: f32,
    #[serde(default)]
    pub aoe_radius: f32,
    #[serde(default = "default_min_level")]
    pub min_level: i32,
    #[serde(default)]
    pub classes: Vec<String>,

    // Corpse / resurrection Slice 3 — for a `target_type == "CORPSE"` res spell,
    // the percentage of THAT death's lost xp refunded on accept (25/50/75 for the
    // Cleric tiers, 20 for the Paladin "Reclaim Soul"). 0 for every non-res spell.
    #[serde(default)]
    pub res_xp_percent: f32,
    /// Summon Food / Summon Drink (food slice 2, user call 2026-10-15,
    /// Monsters and Memories' shape): a SUMMON_ITEM spell conjures
    /// `summon_item` into the caster's bags, `summon_count` of them: one at
    /// the level the class gets the spell and one more per
    /// `SUMMON_LEVELS_PER_EXTRA` levels, capped at `summon_max`.
    #[serde(default)]
    pub summon_item: String,
    #[serde(default)]
    pub summon_max: u32,
    /// Per-class level requirements on a spell several classes share
    /// (Summon Drink: Magician 1, Shaman 2, Cleric 3, Druid 10). A class
    /// absent here uses `min_level`. Read by the cast gate's level check
    /// and by the summon count's base; the client carries the same table.
    #[serde(default)]
    pub class_min_levels: std::collections::HashMap<String, i32>,

    // Track 6 sub-task 4a — buff fields applied to the target (or
    // caster for SELF spells) after the immediate damage/heal lands.
    /// Heal-over-time. `hot_hps` HP/sec for `hot_duration` seconds.
    #[serde(default)]
    pub hot_hps: f32,
    #[serde(default)]
    pub hot_duration: f32,
    /// Mana regen buff (Clarity / Breeze / Mana Weave).
    #[serde(default)]
    pub mp_regen_hps: f32,
    #[serde(default)]
    pub mp_regen_duration: f32,
    /// Lich Form toggle. When true, applying this spell pushes a
    /// LichForm buff (infinite duration) that disables HP regen and
    /// grants `lich_mp_regen` MP/sec. Re-casting clears.
    #[serde(default)]
    pub is_lich_form: bool,
    #[serde(default)]
    pub lich_mp_regen: f32,

    // Track 6 sub-task 4b — primary stat buff deltas. Any spell with a
    // non-zero primary_stat_buff_duration applies a StatBuff to the
    // target carrying these deltas. Mirror of GDScript SpellData's
    // str_buff / agi_buff / int_buff / wis_buff / con_buff /
    // max_hp_buff / max_mp_buff fields (charisma_buff and dexterity_buff
    // don't exist in the GDScript data — STR / AGI / INT / WIS / CON
    // + max_hp / max_mp are the authored set).
    #[serde(default)]
    pub str_buff: i32,
    #[serde(default)]
    pub agi_buff: i32,
    #[serde(default)]
    pub int_buff: i32,
    #[serde(default)]
    pub wis_buff: i32,
    #[serde(default)]
    pub con_buff: i32,
    #[serde(default)]
    pub max_hp_buff: f32,
    #[serde(default)]
    pub max_mp_buff: f32,
    #[serde(default)]
    pub primary_stat_buff_duration: f32,

    // Track 6 sub-task 4c — combat-modifier buffs.
    #[serde(default)]
    pub move_speed_mult: f32,
    #[serde(default)]
    pub move_speed_duration: f32,
    #[serde(default)]
    pub haste_amount: f32,
    #[serde(default)]
    pub haste_duration: f32,
    #[serde(default)]
    pub damage_shield_amount: f32,
    #[serde(default)]
    pub damage_shield_duration: f32,
    #[serde(default)]
    pub absorb_amount: f32,
    #[serde(default)]
    pub accuracy_buff: f32,
    #[serde(default)]
    pub crit_buff: f32,
    #[serde(default)]
    pub stat_buff_duration: f32,

    // Track 11 — pet summon. `pet_type` keys into pet_templates.rs
    // (currently "skeleton"). Only meaningful when target_type ==
    // "PET_SUMMON".
    #[serde(default)]
    pub pet_type: String,

    // Spell batch step 2 — what a PORT spell does: "bind" returns the caster
    // to their bind point (Gate), "safe" lands at the nearest safe area's
    // arrival point (Succor, Evacuate). `port_group` moves the caster's
    // alive group members in reach along with them (Evacuate). The
    // destination is never the client's: CastSpell carries a name and a
    // target id and nothing else.
    #[serde(default)]
    pub port: String,
    #[serde(default)]
    pub port_group: bool,

    // A Bard song (spell batch step 4). Songs neither start nor honour the
    // global cooldown, or twisting (songs cast back to back) stops working.
    // Mirrors the client's `is_song`; the lockstep check compares it.
    #[serde(default)]
    pub is_song: bool,

    // Damage over time (spell batch step 5): `dot_dps` per second for
    // `dot_duration` seconds after the direct hit, dealt in whole ticks of
    // `DOT_TICK_SECS`. Mirrors the client's `dot_dps` / `dot_duration`.
    #[serde(default)]
    pub dot_dps: f32,
    #[serde(default)]
    pub dot_duration: f32,

    // Track 12 Piece C — generic duration field (currently used by
    // PET_CHARM spells for how long the target stays charmed; future
    // mechanics with a single duration knob can reuse). Distinct
    // from cc_duration / slow_duration / etc. which keep their own
    // CC-specific fields.
    #[serde(default)]
    pub duration: f32,

    // Track 6 sub-task 4d — CC fields.
    #[serde(default)]
    pub cc_duration: f32,
    #[serde(default)]
    pub root_duration: f32,
    #[serde(default)]
    pub slow_amount: f32,
    #[serde(default)]
    pub slow_duration: f32,
    #[serde(default)]
    pub attack_slow_amount: f32,
    #[serde(default)]
    pub attack_slow_duration: f32,
    #[serde(default)]
    pub silence_duration: f32,
    #[serde(default)]
    pub is_dispel: bool,
    /// How far this spell reaches its target, metres; 0 means
    /// `DEFAULT_SPELL_RANGE` (use `reach()`). Per-spell since 2026-10-19
    /// (user, on Monsters and Memories' baseline: every single-target spell
    /// reaches 30 m, heals and nukes alike). An area spell's own size is
    /// `aoe_radius`, separate from this.
    #[serde(default)]
    pub range: f32,
}

/// The reach of a spell that names none: Monsters and Memories' 30 m for every
/// single-target spell (their wiki, re-checked 2026-10-19). Must stay inside
/// `MIN_LEASH_RANGE`, or a mob could be hit from beyond its own leash.
pub const DEFAULT_SPELL_RANGE: f32 = 30.0;

fn default_min_level() -> i32 { 1 }

fn spells() -> &'static HashMap<String, Spell> {
    static SPELLS: OnceLock<HashMap<String, Spell>> = OnceLock::new();
    SPELLS.get_or_init(|| {
        let parsed: SpellsFile = toml::from_str(SPELLS_TOML)
            .expect("spells.toml must parse — fix the embedded file or re-run tools/export_spells.gd");
        parsed
            .spells
            .into_iter()
            .map(|s| (s.name.clone(), s))
            .collect()
    })
}

/// Look up a spell by its canonical name (matches `SpellData.spell_name`
/// on the client). Returns `None` for unknown spells — the client may
/// have a spell the server's table doesn't, in which case the server
/// rejects the cast (logged at debug level).
pub fn lookup(name: &str) -> Option<&'static Spell> {
    spells().get(name)
}

/// Every spell the server knows (the tests that hold a rule over all of
/// them, such as reach inside the leash floor).
pub fn all() -> impl Iterator<Item = &'static Spell> {
    spells().values()
}

/// Map a weapon's `proc_damage_type` (a `u8` authored in the client's
/// `SpellData.DamageType` enum space: FIRE=0, ICE=1, LIGHTNING=2, ARCANE=3,
/// HEALING=4, HOLY=5, NATURE=6, SPIRIT=7, SHADOW=8, NONE=9) onto the wire
/// `DamageType`. Mirror of the client's `combat.gd::_spell_to_net_damage_type`
/// so the server-rolled proc flashes the same element the item author intended.
/// HEALING / NONE / anything unknown fall back to Physical (no elemental flash).
pub fn proc_damage_type_to_wire(t: u8) -> protocol::world::DamageType {
    use protocol::world::DamageType;
    match t {
        0 => DamageType::Fire,
        1 => DamageType::Ice,
        2 => DamageType::Lightning,
        3 => DamageType::Arcane,
        5 => DamageType::Holy,
        6 => DamageType::Nature,
        7 => DamageType::Spirit,
        8 => DamageType::Shadow,
        _ => DamageType::Physical,
    }
}

/// Map a damage_type string from the TOML onto the wire enum. The
/// `Hit` broadcast carries this so peers render the right color flash.
pub fn parse_damage_type(s: &str) -> protocol::world::DamageType {
    use protocol::world::DamageType;
    match s {
        "FIRE" => DamageType::Fire,
        "ICE" => DamageType::Ice,
        "LIGHTNING" => DamageType::Lightning,
        "ARCANE" => DamageType::Arcane,
        "HOLY" => DamageType::Holy,
        "NATURE" => DamageType::Nature,
        "SPIRIT" => DamageType::Spirit,
        "SHADOW" => DamageType::Shadow,
        "POISON" => DamageType::Poison,
        _ => DamageType::Physical,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_toml_parses() {
        let table = spells();
        assert!(!table.is_empty(), "spells.toml produced no entries");
    }

    /// The nine direct-damage spells ported 2026-10-05 from the client's
    /// definitions. Each used to be refused as an unknown spell. Class,
    /// level and damage are the client's values; this pins them so a
    /// regenerated toml that drops one fails here instead of in play.
    #[test]
    fn ported_direct_damage_spells_resolve() {
        let expected: [(&str, &str, i32, f32, &str); 9] = [
            ("Blizzard", "Wizard", 8, 65.0, "ICE"),
            ("Thunder Clap", "Wizard", 10, 100.0, "LIGHTNING"),
            ("Bloodfire", "Sorcerer", 4, 40.0, "FIRE"),
            ("Void Lance", "Sorcerer", 6, 55.0, "ARCANE"),
            ("Tempest Bolt", "Sorcerer", 10, 65.0, "LIGHTNING"),
            ("Cascade of Stars", "Enchanter", 12, 55.0, "ARCANE"),
            ("Chorus of Misery", "Bard", 10, 45.0, "ARCANE"),
            ("Feral Shriek", "Beast Master", 4, 35.0, "SPIRIT"),
            ("Judgment", "Paladin", 12, 80.0, "HOLY"),
        ];
        for (name, class, level, damage, dtype) in expected {
            let s = lookup(name).unwrap_or_else(|| panic!("{name} missing from spells.toml"));
            assert_eq!(s.target_type, "ENEMY", "{name}");
            assert_eq!(s.damage_type, dtype, "{name}");
            assert_eq!(s.min_level, level, "{name}");
            assert!((s.base_damage - damage).abs() < 0.01, "{name} damage {}", s.base_damage);
            assert_eq!(s.classes, vec![class.to_string()], "{name}");
            assert!(s.mana_cost > 0.0, "{name} must cost mana");
        }
    }

    /// Spell batch step 1 (user numbers, 2026-10-05 and 10-07): Slow 5% for
    /// 30 s at 10 mana, Torpor 10% for a minute at 20 mana with no heal,
    /// neither with a cooldown of its own; Aria of Dismay 8%.
    #[test]
    fn the_attack_slows_carry_the_decided_numbers() {
        let slow = lookup("Slow").expect("Slow");
        assert!((slow.attack_slow_amount - 0.05).abs() < 1e-6);
        assert!((slow.attack_slow_duration - 30.0).abs() < 1e-6);
        assert!((slow.mana_cost - 10.0).abs() < 1e-6);
        assert!((slow.cast_time - 1.0).abs() < 1e-6);
        assert_eq!(slow.cooldown, 0.0, "no cooldown of its own");
        let torpor = lookup("Torpor").expect("Torpor is on the server now");
        assert_eq!(torpor.target_type, "ENEMY");
        assert!((torpor.attack_slow_amount - 0.10).abs() < 1e-6);
        assert!((torpor.attack_slow_duration - 60.0).abs() < 1e-6);
        assert!((torpor.mana_cost - 20.0).abs() < 1e-6);
        assert!((torpor.cast_time - 1.5).abs() < 1e-6);
        assert_eq!(torpor.cooldown, 0.0);
        assert_eq!(torpor.heal_amount, 0.0, "no heal");
        assert_eq!(torpor.min_level, 20);
        assert_eq!(torpor.classes, vec!["Shaman".to_string()]);
        let aria = lookup("Aria of Dismay").expect("Aria");
        assert!((aria.attack_slow_amount - 0.08).abs() < 1e-6);
        assert!(aria.attack_slow_duration > 0.0, "the server applies it for a while");
    }

    /// Warder's Mend, the one client-only pet spell, resolves (2026-10-07).
    #[test]
    fn warders_mend_resolves_as_a_pet_heal() {
        let s = lookup("Warder's Mend").expect("Warder's Mend in spells.toml");
        assert_eq!(s.target_type, "PET_HEAL");
        assert!((s.heal_amount - 60.0).abs() < 0.01);
        assert_eq!(s.classes, vec!["Beast Master".to_string()]);
        assert_eq!(s.min_level, 1);
    }

    /// Spell batch step 4: the six Bard songs are the only spells exempt from
    /// the global cooldown, so `is_song` must be set on exactly them (the
    /// client's `spell_definitions.gd` carries the same six; the lockstep
    /// check compares the flag).
    #[test]
    fn exactly_the_six_bard_songs_are_songs() {
        let mut songs: Vec<&str> = spells()
            .values()
            .filter(|s| s.is_song)
            .map(|s| s.name.as_str())
            .collect();
        songs.sort_unstable();
        assert_eq!(
            songs,
            vec![
                "Anthem of the Hunt",
                "Aria of Dismay",
                "Mana Weave",
                "Poet's Mending",
                "Selos' Melody",
                "Wanderer's Chord",
            ]
        );
        assert!(!lookup("Chorus of Misery").unwrap().is_song, "a Bard nuke is not a song");
    }

    #[test]
    fn fireball_resolves() {
        let s = lookup("Fireball").expect("Fireball in table");
        assert_eq!(s.target_type, "ENEMY");
        assert_eq!(s.damage_type, "FIRE");
        assert!((s.base_damage - 50.0).abs() < 0.01);
        assert!((s.mana_cost - 30.0).abs() < 0.01);
    }

    #[test]
    fn healing_light_is_ally_heal() {
        let s = lookup("Healing Light").expect("Healing Light in table");
        assert_eq!(s.target_type, "ALLY");
        assert!((s.heal_amount - 60.0).abs() < 0.01);
    }

    #[test]
    fn complete_heal_is_max() {
        let s = lookup("Complete Heal").expect("Complete Heal in table");
        assert!((s.heal_amount - 9999.0).abs() < 0.01);
    }

    #[test]
    fn damage_type_parser_handles_known_and_unknown() {
        use protocol::world::DamageType;
        assert!(matches!(parse_damage_type("FIRE"), DamageType::Fire));
        assert!(matches!(parse_damage_type("HOLY"), DamageType::Holy));
        assert!(matches!(parse_damage_type("UNKNOWN"), DamageType::Physical));
    }

    #[test]
    fn proc_damage_type_u8_maps_from_spelldata_space_to_wire() {
        use protocol::world::DamageType;
        // SpellData space: FIRE=0, ICE=1, ... (offset from wire, where Physical=0).
        assert!(matches!(proc_damage_type_to_wire(0), DamageType::Fire));
        assert!(matches!(proc_damage_type_to_wire(1), DamageType::Ice));
        assert!(matches!(proc_damage_type_to_wire(8), DamageType::Shadow));
        // HEALING(4) / NONE(9) / unknown -> Physical (no elemental flash).
        assert!(matches!(proc_damage_type_to_wire(4), DamageType::Physical));
        assert!(matches!(proc_damage_type_to_wire(9), DamageType::Physical));
        assert!(matches!(proc_damage_type_to_wire(200), DamageType::Physical));
    }

    #[test]
    fn resurrection_tiers_are_corpse_targeted_with_refund_percents() {
        // Slice 3 — the three Cleric tiers + the Paladin tier, each targeting a
        // CORPSE and carrying its server-authoritative XP-refund percentage.
        for (name, pct, class) in [
            ("Resurrection (Minor)", 25.0_f32, "Cleric"),
            ("Resurrection", 50.0, "Cleric"),
            ("Resurrection II", 75.0, "Cleric"),
            ("Reclaim Soul", 20.0, "Paladin"),
        ] {
            let s = lookup(name).unwrap_or_else(|| panic!("{name} missing from spells.toml"));
            assert_eq!(s.target_type, "CORPSE", "{name} must target a corpse");
            assert!((s.res_xp_percent - pct).abs() < 0.01, "{name} refund percent");
            assert!(s.classes.iter().any(|c| c == class), "{name} castable by {class}");
        }
    }

    #[test]
    fn every_spell_is_class_and_level_tagged() {
        // The Phase 1 cast gate (tick.rs) rejects a cast when the caster's
        // class isn't in `spell.classes` or their level < `spell.min_level`.
        // It leans on every spell carrying that data — an untagged spell (empty
        // classes) would reject EVERY caster and silently break casting for it.
        // Guard the invariant here so a newly-authored spell can't reopen the gap.
        for s in spells().values() {
            assert!(
                !s.classes.is_empty(),
                "{} has no classes — cast gate would reject all casters",
                s.name
            );
            assert!(s.min_level >= 1, "{} has min_level {} (< 1)", s.name, s.min_level);
        }
    }

    #[test]
    fn cast_gate_eligibility_matches_class_and_level() {
        // Mirror of the tick.rs gate predicate (class in spell.classes AND
        // level >= spell.min_level), pinned to real table rows so a data or
        // logic drift trips a test rather than shipping an exploit or a
        // false rejection.
        let eligible = |name: &str, class: &str, level: i32| {
            let s = lookup(name).unwrap_or_else(|| panic!("{name} missing from spells.toml"));
            s.classes.iter().any(|c| c == class) && level >= s.min_level
        };
        // Right class, lowest bar: Magician casts Fireball (min_level 1).
        assert!(eligible("Fireball", "Magician", 1));
        // Wrong class: a max-level Cleric still can't cast the Magician's Fireball.
        assert!(!eligible("Fireball", "Cleric", 60));
        // Level gate: Meteor is Wizard, min_level 18.
        assert!(!eligible("Meteor", "Wizard", 17), "below min_level must fail");
        assert!(eligible("Meteor", "Wizard", 18), "at min_level must pass");
        // Wrong class trumps level entirely.
        assert!(!eligible("Meteor", "Cleric", 60));
    }

    #[test]
    fn ported_client_spells_resolve() {
        // Life Drain + Dark Shroud were client-only (playtest 2026-07-22: server
        // dropped the cast as "unknown spell", mana spent, no effect). Ported into
        // spells.toml; lock them so the client/server drift can't silently reopen.
        let ld = lookup("Life Drain").expect("Life Drain ported into spells.toml");
        assert_eq!(ld.target_type, "ENEMY");
        assert!(ld.classes.iter().any(|c| c == "Blood Mage"));
        assert_eq!(ld.min_level, 6);
        assert!(ld.heal_amount > 0.0, "Life Drain is a lifetap (self-heal)");
        let ds = lookup("Dark Shroud").expect("Dark Shroud ported into spells.toml");
        assert_eq!(ds.target_type, "ENEMY");
        assert!(ds.classes.iter().any(|c| c == "Shadow Knight"));
        assert_eq!(ds.min_level, 10);
    }
}

impl Spell {
    /// How far this spell reaches its target: its own `range`, else the
    /// default. The one reach every targeted cast is checked against.
    pub fn reach(&self) -> f32 {
        if self.range > 0.0 { self.range } else { DEFAULT_SPELL_RANGE }
    }

    /// The level `class` needs for this spell: its own entry in
    /// `class_min_levels`, else `min_level`.
    pub fn required_level(&self, class: &str) -> i32 {
        self.class_min_levels
            .get(class)
            .copied()
            .unwrap_or(self.min_level)
    }
}

/// Summon Food / Drink: one more item per this many levels above the level
/// the class got the spell (a tuning knob; Monsters and Memories scales 1 to
/// 4 by level without publishing the steps).
pub const SUMMON_LEVELS_PER_EXTRA: i32 = 1;

/// How many of a SUMMON_ITEM spell's item a caster of `class` at
/// `caster_level` conjures: 1 at the class's level for the spell, one more
/// per `SUMMON_LEVELS_PER_EXTRA` levels, never more than `summon_max` (and
/// never less than one).
pub fn summon_count(spell: &Spell, class: &str, caster_level: i32) -> u32 {
    let base = spell.required_level(class);
    let extra = (caster_level - base).max(0) / SUMMON_LEVELS_PER_EXTRA;
    ((1 + extra) as u32).min(spell.summon_max.max(1))
}

#[cfg(test)]
mod summon_tests {
    use super::*;

    // Summon Food: Magician 1, Cleric 9, Shaman 9, Druid 14; one loaf at the
    // class's level, one more per level after (user, 2026-10-19), ten at most.
    #[test]
    fn summon_count_scales_from_the_class_level_and_caps_at_ten() {
        let food = lookup("Summon Food").expect("Summon Food in spells.toml");
        assert_eq!(food.required_level("Magician"), 1);
        assert_eq!(food.required_level("Druid"), 14);
        assert_eq!(food.required_level("Warrior"), food.min_level, "a class with no entry uses min_level");
        assert_eq!(summon_count(food, "Magician", 1), 1);
        assert_eq!(summon_count(food, "Magician", 2), 2);
        assert_eq!(summon_count(food, "Magician", 9), 9);
        assert_eq!(summon_count(food, "Magician", 10), 10);
        assert_eq!(summon_count(food, "Magician", 60), 10);
        assert_eq!(summon_count(food, "Druid", 14), 1);
        assert_eq!(summon_count(food, "Druid", 18), 5);
        assert_eq!(summon_count(food, "Druid", 5), 1, "below the level the gate refuses; the count itself never drops under one");
        let drink = lookup("Summon Drink").expect("Summon Drink in spells.toml");
        assert_eq!(drink.required_level("Shaman"), 2);
        assert_eq!(drink.required_level("Cleric"), 3);
        assert_eq!(drink.required_level("Druid"), 10);
        assert_eq!(drink.summon_max, 10);
        assert!(drink.summon_item.ends_with("conjured_water.tres"));
    }

    #[test]
    fn a_spell_reaches_its_own_range_or_thirty_metres() {
        let smite = lookup("Smite").expect("Smite in spells.toml");
        assert_eq!(smite.range, 0.0, "no spell names its own range yet");
        assert_eq!(smite.reach(), DEFAULT_SPELL_RANGE);
        assert_eq!(DEFAULT_SPELL_RANGE, 30.0);
        let mut far = smite.clone();
        far.range = 12.0;
        assert_eq!(far.reach(), 12.0);
    }
}

